create or replace TABLE SZD_PRODUCTION.CORE_REL.T_CONSIGNOR_ORDER_LIST_LINE_1 (
	TRADER_REFERENCE_NR VARCHAR(250) NOT NULL COMMENT 'Natural Key/Business Key - This is a reference assigned by the declarant for the goods covered by the declaration.',
	ORDER_DT DATE NOT NULL COMMENT 'Natural Key/Business Key - The date when the goods were ordered by the consignor.',
	ITEM_POSITION_SEQ NUMBER(38,0) NOT NULL COMMENT 'Natural Key/Business Key - The position number within the order (truck load)',
	PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product (only for products from WWT).',
	CUSTOMS_PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the customs product (only for products from BEI).',
	ORIGIN_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the origin country_1 of the product.',
	ALCOHOLIC_BEVERAGE_TAX_RATE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the tax rate for alcoholic beverages within the country_1 (only BEI).',
	INVOICE_FINANCE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the invoice.',
	INVOICE_POSITION_FINANCE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the invoice position.',
	PURCHASE_ORDER_ITEM_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The order position identifier. The first part describes the position of the product and the second part describes the position of the variant within the product.',
	PRODUCT_NR VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - The product number of the item_1 (IAN for a product from WWT, SAP Item_1 number for a product from BEI).',
	ADDITIONAL_CD VARCHAR(50) NOT NULL COMMENT 'An additional code that is appended to the product number.',
	PRODUCT_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The name of product either from BEI or WWT.',
	NET_WEIGHT_MEAS NUMBER(38,5) NOT NULL COMMENT 'Fact - addtive - The net weight in KG of the goods.',
	GROSS_WEIGHT_MEAS NUMBER(38,5) NOT NULL COMMENT 'Fact - addtive - The gross weight in KG of the goods.',
	WEIGHT_UOM_ID NUMBER(38,0) NOT NULL COMMENT 'Id of the unit_1 the weight is measured in.',
	ALLOCATION_CNT NUMBER(38,0) NOT NULL COMMENT 'Fact - additive - Number of items in a carton.',
	PACKAGES_CNT NUMBER(38,0) NOT NULL COMMENT 'Fact - additive - Number of packages/cartons.',
	PACKAGES_UOM_ID NUMBER(38,0) NOT NULL COMMENT 'Id of the unit_1 the packages are counted.',
	ITEM_CNT NUMBER(38,0) NOT NULL COMMENT 'Fact - additive - The item_1 count (usually the product of allocation count and package_1 count)',
	ITEM_UOM_ID NUMBER(38,0) NOT NULL COMMENT 'Id of the unit_1 the items are counted.',
	NET_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The net value of the order position.',
	NET_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency of the net value.',
	ORIGINAL_AMOUNT_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The original amount of the order position as declared on the invoice (only BEI).',
	ORIGINAL_AMOUNT_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency of the original amount (only BEI).',
	ITEM_PRICE_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The price of the item_1, uses the same currency as the net value (only WWT).',
	FREIGHT_COST_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The amount of freight costs (only BEI).',
	FREIGHT_COST_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency of the freight cost amount (only BEI).',
	INSURANCE_COST_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The amount of insurance costs (only BEI).',
	INSURANCE_COST_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency of the insurance cost amount (only BEI).',
	LICENSE_COST_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The amount of license costs (only BEI).',
	LICENSE_COST_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency of the license cost amount (only BEI).',
	ABV_PCT NUMBER(38,5) NOT NULL COMMENT 'Fact - non additive - Alcoholic percentage of a beverage.',
	INBOUND_ITEM_NR VARCHAR(250) COMMENT 'Descriptive Attribute - A delivery position reference number (only BEI).',
	TAX_INDICATOR_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - A text containing information regarding the tax (only BEI).',
	ARTICLE_VARIANT_NR VARCHAR(250) COMMENT 'Descriptive Attribute - A article variant number from the source system (only BEI).',
	ADDITIONAL_CODES_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - Additional code to the commodity code (customs tariff number) (only BEI).',
	GTIN_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The B2B GTIN number of the article (only BEI).',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) NOT NULL COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	BATCH_NR VARCHAR(50) COMMENT 'Descriptive Attribute - The number of the batch the product is part of (only for products from WWT).',
	constraint PK_CONSIGNOR_ORDER_LIST_LINE primary key (TRADER_REFERENCE_NR, ORDER_DT, ITEM_POSITION_SEQ)
)COMMENT='Entity - Transactional - Transaction - This is a specific order position within the BEI consignor order list. - Source - BEI Report'
;